      expect(out.output).toContain("express@4.18.2  license=MIT  status=APPROVED");
      expect(out.output).toContain(
        "Total: 2  Approved: 2  Denied: 0  Unknown: 0",
      );
      expect(out.output).toContain("Verdict: COMPLIANT");
    },
